---@type IVoicePackData
local IVoicePackData = Plugins.Require("voice_pack", "common.data.i_voice_pack_data")
---@class SVoicePackData : IVoicePackData
local SVoicePackData = class("SVoicePackData", IVoicePackData)

function SVoicePackData:initData()
    WebService.GetPlayerVoicePackData(self.player.userId, function(voiceData)
        self.voices = StringUtil.split(voiceData or "", ",", nil, true)
        self:syncData()
    end)
end

function SVoicePackData:addVoicePack(id)
    if not IVoicePackData.addVoicePack(self, id) then
        return
    end
    self:saveData()
    self:syncData()
end

function SVoicePackData:removeVoicePack(id)
    if not IVoicePackData.removeVoicePack(self, id) then
        return
    end
    self:saveData()
    self:syncData()
end

---@private
function SVoicePackData:saveData()
    local voiceData = table.concat(self.voices, ",")
    WebService.SetPlayerVoicePackData(self.player.userId, voiceData)
end

---@private
function SVoicePackData:syncData()
    self.player:sendPacket({
        pid = "SyncVoicePackData",
        voices = self.voices,
    })
end

return SVoicePackData